{
  "viz_type": "line_chart",
  "x_axis": {
    "name": "date",
    "format": "%Y-%m"
  },
  "y_axis": {
    "name": "revenue",
    "title": "Revenue (USD)"
  },
  "agg": null,
  "title": "Monthly Revenue Over Time by Region and Channel" 
}

{
  "viz_type": "bar_chart",
  "x_axis": {
    "name": "channel",
    "type": "nominal"
  },
  "y_axis": {
    "name": "avg_satisfaction",
    "type": "quantitative"
  },
  "agg": [
    {
      "column": "region",
      "value": "North"
    }
  ],
  "title": "Average Satisfaction per Channel in North Region" 
}

{
  "viz_type": "surface",
  "x_axis": {
    "name": "units",
    "type": "quantitative"
  },
  "y_axis": {
    "name": "price",
    "type": "quantitative"
  },
  "z_axis": {
    "name": "revenue",
    "type": "quantitative"
  },
  "agg": [
    {
      "column": "region",
      "type": "nominal"
    }
  ],
  "title": "Revenue vs Price and Units by Region" 
}

{
  "viz_type": "bar_chart",
  "x_axis": {
    "name": "Region",
    "type": "nominal",
    "values": ["South", "North", "East"]
  },
  "y_axis": {
    "name": "Distinct Days Sold",
    "type": "quantitative"
  },
  "agg": {
    "date": {
      "func": "nunique"
    }
  },
  "title": "Number of Distinct Days Sold by Region" 
}

{
  "viz_type": "AreaChart",
  "x_axis": {
    "type": "DateAxis",
    "format": "%Y-%m"
  },
  "y_axis": {
    "type": "QuantitativeAxis",
    "title": "Revenue"
  },
  "agg": {
    "date": "Month",
    "region": null,
    "channel": null
  },
  "title": "Monthly Revenue by Region and Channel" 
}

{
  "viz_type": "bar_chart",
  "x_axis": {
    "name": "channel",
    "type": "nominal"
  },
  "y_axis": {
    "name": "average_satisfaction",
    "type": "quantitative"
  },
  "agg": [
    {
      "column": "units",
      "condition": "> 20",
      "func": "avg",
      "alias": "average_satisfaction"
    }
  ],
  "title": "Average Satisfaction per Channel for Orders of at Least 20 Units" 
}

{
  "viz_type": "bar_chart",
  "x_axis": {
    "name": "channel",
    "type": "nominal"
  },
  "y_axis": {
    "name": "units",
    "type": "quantitative"
  },
  "agg": [
    {
      "column": "satisfaction",
      "condition": "<=3",
      "operator": "and"
    }
  ],
  "title": "Units Sold per Channel where Satisfaction is 3 or Lower" 
}

{
  "viz_type": "bar_chart",
  "x_axis": {
    "name": "region",
    "category": "nominal"
  },
  "y_axis": {
    "name": "revenue",
    "unit": "USD"
  },
  "agg": [
    {"column": "region", "operator": "in", "values": ["North", "South"]},
    {"column": "channel", "operator": "any"}
  ],
  "title": "Revenue by Region for North and South Channels" 
}

{
  "viz_type": "bar_chart",
  "x_axis": {
    "name": "region",
    "filter": ["East", "West"]
  },
  "y_axis": {
    "name": "revenue"
  },
  "agg": null,
  "title": "Revenue by Region (Excluding North and South)"
}

{
  "viz_type": "bar_chart",
  "x_axis": {
    "name": "region",
    "type": "nominal"
  },
  "y_axis": {
    "name": "revenue",
    "type": "quantitative"
  },
  "agg": [
    {
      "column": "price",
      "range": [20, 60],
      "func": "mean"
    }
  ],
  "title": "Revenue by Region for Prices between $20 and $60" 
}

{
  "viz_type": "bar_chart",
  "x_axis": {
    "name": "region",
    "type": "nominal"
  },
  "y_axis": {
    "name": "revenue",
    "type": "quantitative",
    "agg": "sum"
  },
  "filter": {
    "condition": "units > 500"
  },
  "title": "Online Revenue by Region (Orders above 500)",
  "x_axis_labels": true,
  "y_axis_labels": true
}

{
  "viz_type": "bar_chart",
  "x_axis": {
    "name": "region",
    "type": "nominal"
  },
  "y_axis": {
    "name": "revenue",
    "type": "quantitative"
  },
  "agg": [
    {
      "column": "channel",
      "type": "nominal"
    }
  ],
  "title": "Revenue by Channel, Broken Down by Region" 
}

{
  "viz_type": "bar_chart",
  "x_axis": {
    "name": "units",
    "type": "quantitative"
  },
  "y_axis": {
    "name": "price",
    "type": "quantitative"
  },
  "agg": [
    {
      "column": "region",
      "type": "nominal"
    }
  ],
  "title": "Price vs Units Sold by Region",
  "x_label": "Units Sold",
  "y_label": "Price",
  "color_axis": "region" 
}

{
  "viz_type": "bar_chart",
  "x_axis": {
    "name": "channel",
    "type": "nominal"
  },
  "y_axis": {
    "name": "satisfaction",
    "type": "quantitative"
  },
  "agg": [
    {
      "column": "region",
      "type": "nominal"
    }
  ],
  "title": "Distribution of Satisfaction by Channel and Region" 
}

{
  "viz_type": "bar_chart",
  "x_axis": {
    "name": "Station Name",
    "type": "nominal"
  },
  "y_axis": {
    "name": "Average Max Temp",
    "type": "quantitative"
  },
  "agg": [
    {
      "column": "Max Temp",
      "func": "mean"
    }
  ],
  "title": "Average Maximum Temperature per Station" 
}

{
  "viz_type": "bar_chart",
  "x_axis": {
    "name": "Month",
    "type": "categorical",
    "values": [
      "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"
    ]
  },
  "y_axis": {
    "name": "Average Max Temp (°C)",
    "type": "quantitative",
    "agg": "mean"
  },
  "title": "Average Maximum Temperature by Month",
  "x_axis_config": {
    "rotation": 45
  }
}

{
  "viz_type": "line_chart",
  "x_axis": {
    "type": "date",
    "format": "%Y-%m"
  },
  "y_axis": {
    "name": "Max Temp (°C)",
    "unit": "",
    "scale": "linear"
  },
  "agg": [
    {
      "column": "Station Name",
      "func": "mean"
    }
  ],
  "title": "Monthly Average Max Temperature by Station",
  "data": {
    "x": "Date",
    "y": "Max Temp"
  },
  "stations": [
    {
      "name": "Cerro Azul",
      "color": "#3498db"
    },
    {
      "name": "Valle Seco",
      "color": "#f1c40f"
    },
    {
      "name": "Playa Norte",
      "color": "#e74c3c"
    }
  ]
}

{
  "viz_type": "line_chart",
  "x_axis": {
    "name": "Date",
    "type": "datetime"
  },
  "y_axis": [
    {
      "name": "Min Temp",
      "type": "quantitative"
    },
    {
      "name": "Max Temp",
      "type": "quantitative"
    }
  ],
  "agg": {
    "min_temp_max_temp_corr": "pearson_correlation"
  },
  "title": "Relationship between Min and Max Temperatures" 
}

{
  "viz_type": "line_chart",
  "x_axis": {
    "name": "Date",
    "format": "%Y-%m-%d"
  },
  "y_axis": [
    {
      "name": "Min Temp (°C)",
      "format": ".1f"
    },
    {
      "name": "Max Temp (°C)",
      "format": ".1f"
    }
  ],
  "agg": {
    "min_temp_max_temp_ratio": {
      "calculation": "(min_temp / max_temp) * 100",
      "color": "#ff69b4"
    },
    "rainfall": {
      "color": "#66d9ef"
    },
    "humidity": {
      "size": 10,
      "color": "#33cc33"
    }
  },
  "title": "Temperature and Precipitation Data",
  "legend_position": "bottom right",
  "marker_size": ["humidity"]
}

{
  "viz_type": "bar_chart",
  "x_axis": {
    "name": "Station Name",
    "type": "nominal"
  },
  "y_axis": [
    {
      "name": "Min Temp (°C)",
      "format": ".1f"
    },
    {
      "name": "Max Temp (°C)",
      "format": ".1f"
    }
  ],
  "agg": [
    {
      "name": "Rainfall (mm)"
    }
  ],
  "title": "Temperature Range by Station",
  "color_axis": {
    "name": "Humidity (%)",
    "type": "quantitative"
  },
  "group_by": ["Station Name"],
  "x_axis_config": {
    "rotation": 90
  }
}

{
  "viz_type": "bar_chart",
  "x_axis": {
    "name": "Station Name",
    "type": "nominal"
  },
  "y_axis": {
    "name": "Max Temp",
    "type": "quantitative"
  },
  "agg": [
    {
      "column": "Date",
      "func": "mean"
    }
  ],
  "title": "Spread of Max Temperature by Station" 
}

{
  "viz_type": "violin_plot",
  "x_axis": {
    "name": "Station Name",
    "type": "nominal"
  },
  "y_axis": {
    "name": "Humidity",
    "type": "quantitative"
  },
  "agg": null,
  "title": "Humidity by Station",
  "data": [
    {
      "station_name": "Cerro Azul",
      "humidity": [30, 35, 40, 45, 50, 55]
    },
    {
      "station_name": "Valle Seco",
      "humidity": [60, 65, 70, 75, 80, 85]
    },
    {
      "station_name": "Playa Norte",
      "humidity": [40, 45, 50, 55, 60, 65]
    }
  ]
}

{
  "viz_type": "bar_chart",
  "x_axis": {
    "name": "Station Name",
    "type": "nominal"
  },
  "y_axis": {
    "name": "Missing Days",
    "type": "quantitative"
  },
  "agg": [
    {
      "column": "Rainfall (mm)",
      "func": "count_nulls"
    }
  ],
  "title": "Missing Rainfall Days per Station" 
}

{
  "viz_type": "bar_chart",
  "x_axis": {
    "name": "Station Name",
    "type": "nominal"
  },
  "y_axis": {
    "name": "Average Rainfall (mm)",
    "type": "quantitative"
  },
  "agg": [
    {
      "column": "Rainfall (mm)",
      "func": "mean"
    }
  ],
  "title": "Average Rainfall per Station",
  "filter": {
    "condition": "not null(Rainfall (mm))"
  }
}

{
  "viz_type": "bar_chart",
  "x_axis": {
    "name": "Station Name",
    "type": "nominal"
  },
  "y_axis": {
    "name": "Max Temp (°C)",
    "type": "quantitative"
  },
  "agg": [
    {
      "column": "Date",
      "func": "max"
    }
  ],
  "title": "Hottest Temperature Ever Recorded at Each Station" 
}

{
  "viz_type": "bar_chart",
  "x_axis": {
    "name": "Station Name",
    "type": "nominal"
  },
  "y_axis": {
    "name": "Min Temp (°C)",
    "type": "quantitative"
  },
  "agg": [
    {
      "func": "min"
    }
  ],
  "title": "Coldest Min Temperature at Each Station" 
}

{
  "viz_type": "bar_chart",
  "x_axis": {
    "name": "Station Name",
    "type": "nominal"
  },
  "y_axis": {
    "name": "Average Humidity (per week)",
    "type": "quantitative"
  },
  "agg": [
    {
      "column": "Humidity",
      "func": "mean",
      "group_by": ["Station Name", "Date"]
    }
  ],
  "title": "Average Humidity per Week by Station" 
}

{
  "viz_type": "bar_chart",
  "x_axis": {
    "name": "Station Name",
    "type": "nominal"
  },
  "y_axis": {
    "name": "Rainfall (mm)",
    "type": "quantitative"
  },
  "agg": [
    {
      "column": "Date",
      "func": "quarter"
    }
  ],
  "title": "Rainfall per Quarter by Station Name" 
}

{
  "viz_type": "bar_chart",
  "x_axis": {
    "name": "Station Name",
    "type": "nominal"
  },
  "y_axis": {
    "name": "Average Max Temp",
    "type": "quantitative"
  },
  "agg": [
    {
      "column": "Date",
      "func": "year"
    }
  ],
  "title": "Average Max Temperature per Year" 
}

{
  "viz_type": "bar_chart",
  "x_axis": {
    "name": "Station Name",
    "type": "nominal"
  },
  "y_axis": {
    "name": "Humidity",
    "type": "quantitative"
  },
  "agg": [
    {
      "column": "Date",
      "condition": " hotter_than_30_degrees() "
    }
  ],
  "title": "Distribution of Humidity on Days Hotter than 30 Degrees" 
}

{
  "viz_type": "bar_chart",
  "x_axis": {
    "name": "Month",
    "type": "datetime",
    "format": "%Y-%m"
  },
  "y_axis": {
    "name": "Max Temp (°C)",
    "unit": "",
    "type": "quantitative"
  },
  "agg": [
    {
      "column": "Date",
      "func": "mean"
    }
  ],
  "title": "Monthly Average Max Temp for Cerro Azul and Playa Norte",
  "filter": ["Station Name", "Cerro Azul", "Playa Norte"],
  "groupby": ["Station Name"]
}

{
  "viz_type": "bar_chart",
  "x_axis": {
    "name": "Station Name",
    "type": "nominal"
  },
  "y_axis": {
    "name": "Average Rainfall (mm)",
    "type": "quantitative"
  },
  "agg": [
    {
      "column": "Date",
      "condition": "(Humidity >= 40) & (Humidity <= 60)"
    }
  ],
  "title": "Average Rainfall per Station on Humid Days" 
}

{
  "viz_type": "bar_chart",
  "x_axis": {
    "title": "Station Name",
    "type": "nominal"
  },
  "y_axis": {
    "title": "Monthly Rainfall (mm)",
    "type": "quantitative"
  },
  "agg": [
    {
      "column": "Rainfall (mm)",
      "func": "mean"
    }
  ],
  "title": "Monthly Rainfall by Station",
  "data": [
    {
      "station_name": "Cerro Azul",
      "rainfall_mean": 12.5
    },
    {
      "station_name": "Valle Seco",
      "rainfall_mean": 8.2
    },
    {
      "station_name": "Playa Norte",
      "rainfall_mean": 10.1
    }
  ]
}

{
  "viz_type": "bar_chart",
  "x_axis": {
    "title": "Station Name",
    "values": [
      "Cerro Azul",
      "Valle Seco"
    ],
    "order": "ascending"
  },
  "y_axis": {
    "title": "Rainfall (mm)",
    "format": ".1f",
    "unit": ""
  },
  "agg": {
    "max_temp": false,
    "min_temp": false
  },
  "title": "Rainfall by Station",
  "x_axis_order": [
    "Cerro Azul",
    "Valle Seco"
  ],
  "y_axis_unit": "",
  "color": "#4CAF50"
}

{
  "viz_type": "bar_chart",
  "x_axis": {
    "name": "Station Name",
    "type": "nominal"
  },
  "y_axis": {
    "name": "Max Temp (°C)",
    "type": "quantitative"
  },
  "agg": [
    {
      "func": "mean",
      "name": "Mean Max Temp"
    }
  ],
  "title": "Variability of Max Temperature at Each Station" 
}

{
  "viz_type": "bar_chart",
  "x_axis": {
    "name": "Station Name",
    "type": "nominal"
  },
  "y_axis": {
    "name": "Number of Observations",
    "type": "quantitative"
  },
  "agg": [
    {
      "column": "Date",
      "func": null
    }
  ],
  "title": "Observations by Station"
}

{
  "viz_type": "bar_chart",
  "x_axis": {
    "name": "Month",
    "format": "%Y-%m"
  },
  "y_axis": [
    {
      "name": "Score",
      "type": "quantitative",
      "stacked": true
    },
    {
      "name": "Seats",
      "type": "quantitative",
      "stacked": true
    }
  ],
  "agg": {
    "plan": {
      "type": "nominal",
      "stacked": true,
      "group_by": ["Month"]
    }
  },
  "title": "Monthly Responses by Plan"
}

{
  "viz_type": "bar_chart",
  "x_axis": {
    "title": "Country",
    "type": "nominal",
    "values": [
      "Country 01",
      "Country 06",
      "Country 11",
      "Country 15",
      "Country 20"
    ]
  },
  "y_axis": {
    "title": "Number of Responses",
    "type": "quantitative",
    "agg": "sum",
    "values": [
      {
        "value": 34,
        "label": "Country 01"
      },
      {
        "value": 23,
        "label": "Country 06"
      },
      {
        "value": 21,
        "label": "Country 11"
      },
      {
        "value": 17,
        "label": "Country 15"
      },
      {
        "value": 14,
        "label": "Country 20"
      }
    ]
  },
  "title": "Top 5 Countries by Number of Responses",
  "agg": "sum",
  "color": "#4CAF50"
}

{
  "viz_type": "bar_chart",
  "x_axis": {
    "name": "product",
    "type": "nominal"
  },
  "y_axis": {
    "name": "avg_score",
    "type": "quantitative"
  },
  "agg": [
    {
      "column": "score",
      "func": "mean"
    }
  ],
  "title": "Average Score per Product for Pro Customers",
  "filter": [
    {
      "column": "plan",
      "value": "Pro"
    }
  ]
}

{
  "viz_type": "bar_chart",
  "x_axis": {
    "name": "plan",
    "type": "nominal"
  },
  "y_axis": {
    "name": "score",
    "type": "quantitative"
  },
  "agg": [
    {
      "column": "plan",
      "condition": "score >= 9",
      "func": "count"
    }
  ],
  "title": "Responses per plan with score 9 or more" 
}

{
  "viz_type": "bar_chart",
  "x_axis": {
    "name": "product",
    "type": "nominal"
  },
  "y_axis": {
    "name": "avg_score",
    "agg": "mean",
    "format": "{:.2f}"
  },
  "color_by": "plan",
  "title": "Average Score per Product by Plan",
  "x_axis_labels": true,
  "legend_position": "bottom"
}

{
  "viz_type": "line_chart",
  "x_axis": {
    "name": "units",
    "type": "quantitative"
  },
  "y_axis": {
    "name": "price",
    "type": "quantitative"
  },
  "agg": [
    {
      "func": "linear_trend"
    }
  ],
  "title": "Price vs Units with Linear Trend Line" 
}

{
  "viz_type": "line_chart",
  "x_axis": {
    "type": "date",
    "format": "%Y-%m"
  },
  "y_axes": [
    {
      "name": "Revenue",
      "title": "Monthly Revenue",
      "agg": "mean"
    },
    {
      "name": "Units",
      "title": "Monthly Units",
      "agg": "sum"
    }
  ],
  "title": "Monthly Sales by Region and Channel",
  "x_axis_label": "Date",
  "y_axis_labels": ["Revenue", "Units"],
  "color": [
    {
      "name": "Region South",
      "color": "#3498db"
    },
    {
      "name": "Region North",
      "color": "#e74c3c"
    },
    {
      "name": "Region East",
      "color": "#1abc9c"
    }
  ],
  "region_filter": true,
  "channel_filter": false
}

{
  "viz_type": "candlestick",
  "x_axis": {
    "name": "date",
    "format": "%Y-%m-%d"
  },
  "y_axis": {
    "name": "price",
    "title": "Price ($)",
    "format": ".2f"
  },
  "agg": null,
  "title": "Daily Price Trend by Region and Channel" 
}

{
  "viz_type": "radar",
  "x_axis": {
    "name": "region",
    "categories": ["South", "North", "East"]
  },
  "y_axis": {
    "name": "units",
    "title": "Units Sold"
  },
  "agg": null,
  "title": "Region Comparison by Units and Revenue" 
}

{
  "viz_type": "line_chart",
  "x_axis": {
    "title": "Country",
    "type": "category"
  },
  "y_axis": {
    "title": "Monthly Average Score",
    "type": "quantitative"
  },
  "agg": [
    {
      "column": "country",
      "func": "mean",
      "alias": "Average Score"
    }
  ],
  "title": "Monthly Average Score by Country" 
}

{
  "viz_type": "bar_chart",
  "x_axis": {
    "name": "Country",
    "type": "nominal",
    "categories": [
      "Country 01",
      "Country 06",
      "Country 11"
    ]
  },
  "y_axis": {
    "name": "Average Score",
    "type": "quantitative",
    "unit": "points"
  },
  "agg": {
    "plan": {
      "group_by": true,
      "aggregation": "mean"
    }
  },
  "title": "Average Score per Plan by Country" 
}

{
  "viz_type": "bar_chart",
  "x_axis": {
    "name": "region",
    "type": "nominal"
  },
  "y_axis": {
    "name": "revenue",
    "type": "quantitative"
  },
  "agg": [
    {
      "column": "channel",
      "value": "Store"
    }
  ],
  "title": "Revenue by Region for Orders Placed in Antarctica",
